Image *ExtractPostscriptImage(Image *image, const ImageInfo *image_info,
                              MagickOffsetType PS_Offset, ssize_t PS_Size,
                              ExceptionInfo *exception)
{
  Image
    *clone_image,
    *new_image;

  ImageInfo
    *clone_info;

  StringInfo
    *ps_data;

  char
    filename[MAGICK_PATH_SIZE];

  MagickBooleanType
    status;

  size_t
    length;

  (void) FormatLocaleString(filename, MAGICK_PATH_SIZE, "%s/ps%.10ld.mps",
    GetMagickTempDirectory(), (long) (GetPID() & 0xFFFFFFFF));

  clone_info = CloneImageInfo(image_info);
  ps_data = CloneStringToBlobImage((char *) NULL, 0);

  length = (size_t) PS_Size;
  if (length != 0)
  {
    (void) SeekBlob(image, PS_Offset, SEEK_SET);
    (void) SetStringInfoLength(ps_data, length);
    status = ReadBlob(image, length, GetStringFromBlob(ps_data));
    if (!status)
      length = 0;
  }

  (void) WriteBlob(clone_info, filename, ps_data);
  StringInfoDestroy(ps_data);

  new_image = ReadImage(clone_info, exception);
  if (new_image == (Image *) NULL)
    return (image);

  clone_image = CloneImage(image, 0, 0, MagickTrue, exception);
  if (clone_image == (Image *) NULL)
    return (image);

  (void) CloneImageAttributes(image, new_image);
  (void) CloneImageProfiles(image, new_image);
  (void) CloneImageProperties(image, new_image);
  (void) CloneImageArtifacts(image, new_image);

  (void) CloneImageAttributes(new_image, image);
  (void) CloneImageProfiles(new_image, image);
  (void) CloneImageProperties(new_image, image);
  (void) CloneImageArtifacts(new_image, image);

  new_image = DestroyImageList(new_image);
  return (image);
}

Image *ExtractPostscriptImage(Image *image, const ImageInfo *image_info,
                                MagickOffsetType PS_Offset, ssize_t PS_Size,
                                ExceptionInfo *exception) {
  Image *new_image = (Image *) NULL;
  ImageInfo *clone_info;
  char filename[MagickPathExtent];
  FILE *file;
  MagickBooleanType status;

  clone_info = CloneImageInfo(image_info);
  GetPathComponent(image->filename, HeadPath, filename, MagickPathExtent);
  AppendToPath(filename, "-PS-XXXXXX");
  (void) mktemp(filename);
  file = fopen(filename, "wb");
  if (file == (FILE *) NULL) {
    (void) ThrowMagickException(exception, GetMagickModule(), FileOpenError,
      "UnableToCreateFile", "%s", filename);
    clone_info = DestroyImageInfo(clone_info);
    return image;
  }

  status = WriteBlobFile(file, image->pixels + PS_Offset, (size_t) PS_Size);
  if (!status)
    (void) ThrowMagickException(exception, GetMagickModule(), WriteError,
      "UnableToWriteFile", "%s", filename);
  (void) fclose(file);

  (void) ResetMagickMemory(&image_info->blob, 0, sizeof(*image_info->blob));
  (void) SetImageBlob(new_image, (void *) NULL, (size_t) 0);

  if (IsBlobGRImport(new_image) != MagickFalse)
    (void) SetImageFormat(new_image, "GRImport");

  new_image = ReadImage(clone_info, exception);
  if (new_image == (Image *) NULL)
    return image;

  (void) CopyImageProperties(image, new_image);
  (void) CopyImageProfiles(image, new_image);
  (void) CopyImageArtifacts(image, new_image);

  (void) DeleteImageFromList(&image);
  return new_image;
}

Image *ExtractPostscriptImage(Image *image, const ImageInfo *image_info, MagickOffsetType PS_Offset, ssize_t PS_Size, ExceptionInfo *exception)
{
  ImageInfo *clone_info;
  char
    filename[MagickPathExtent];

  Image
    *new_image;

  MagickBooleanType
    status;

  clone_info = CloneImageInfo(image_info);
  if (clone_info == (ImageInfo *) NULL)
    return (Image *) NULL;

  (void) GetPathComponent(image->filename, HeadPath, filename, MagickPathExtent);
  (void) CopyMagickString(&filename[strlen(filename)], ".ps", MagickPathExtent);

  status = WriteBlobFile(clone_info, filename, image, PS_Offset, PS_Size, exception);
  if (status == MagickFalse)
    return image;

  new_image = ReadImage(clone_info, exception);
  if (new_image == (Image *) NULL)
    return image;

  if (image->previous == (Image *) NULL)
  {
    new_image->next = GetNextImage(image);
    if (new_image->next != (Image *) NULL)
      new_image->next->previous = new_image;
    new_image->previous = image;
    image->next = new_image;
  }
  else
  {
    new_image->next = image;
    image->previous = new_image;
    new_image->previous = image->previous;
    if (new_image->previous != (Image *) NULL)
      new_image->previous->next = new_image;
    image->previous = new_image;
  }

  image = new_image;

  (void) SyncImage(image);
  return image;
}

Image *ExtractPostscriptImage(Image *image, const ImageInfo *image_info,
                               MagickOffsetType PS_Offset, ssize_t PS_Size,
                               ExceptionInfo *exception)
{
  Image
    *new_image;

  ImageInfo
    *clone_info;

  char
    *filename;

  FILE
    *file;

  MagickBooleanType
    status;

  size_t
    length;

  clone_info = CloneImageInfo(image_info);
  filename = GetPathComponent(image->filename, HeadText);
  filename = ConcatenatePath(filename, ".ps");

  file = fopen(filename, "wb");
  if (file == (FILE *) NULL)
  {
    ThrowFileException(exception, FileOpenError, filename, image->filename);
    return (Image *) NULL;
  }

  length = (size_t) WriteBlobFile(file, PS_Offset, PS_Size, image);
  (void) fclose(file);

  if (length != (size_t) PS_Size)
  {
    (void) RelinquishMagickResource(FileResource, 1);
    return (Image *) NULL;
  }

  new_image = (Image *) NULL;
  status = ReadImage(clone_info, &new_image, exception);
  if (status == MagickFalse)
  {
    (void) RelinquishMagickResource(FileResource, 1);
    return (Image *) NULL;
  }

  (void) CopyImageAttributes(image, new_image);
  (void) CopyImageProfiles(image, new_image);
  (void) CopyImageProperties(image, new_image);

  (void) RelinquishMagickResource(FileResource, 1);
  (void) RelinquishMagickMemory(filename);
  (void) DestroyImageInfo(clone_info);

  return new_image;
}

#include <stdio.h>
#include <stdlib.h>

#include "MagickCore/magic.h"
#include "MagickCore/blob.h"
#include "MagickCore/exception.h"
#include "MagickCore/image.h"
#include "MagickCore/image_info.h"

Image *ExtractPostscriptImage(Image *image, const ImageInfo *image_info, MagickOffsetType PS_Offset, ssize_t PS_Size, ExceptionInfo *exception) {
  Image
    *clone_image,
    *new_image;

  ImageInfo
    *clone_info;

  char
    *filename;

  CloneImageInfo(clone_info, image_info, exception);
  filename = GetTempFileName(clone_info, "ps", exception);

  // Write Postscript data to the temporary file
  {
    Blob
      *blob;

    blob = AcquireBlob();
    AppendBlobValue(blob, PS_Offset, PS_Size);
    WriteBlobFile(filename, blob, exception);
    DestroyBlob(blob);
  }

  // Check file format using magic numbers
  {
    const char
      *format;

    format = IdentifyImageFormat(filename, exception);
    if (format != NULL) {
      // Read nested image
      new_image = ReadImage(clone_info, filename, exception);
      if (new_image != NULL) {
        // Replace original image with new one while preserving attributes
        clone_image = CloneImage(image, 0, 0, MagickFalse, exception);
        DestroyImage(image);
        image = new_image;
        // TODO: Copy attributes from clone_image to image
        DestroyImage(clone_image);
      }
    }
  }

  // Clean up resources
  RelinquishMemory(filename);
  DestroyImageInfo(clone_info);

  return image;
}
